const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Check product table schema
const cols = db.prepare(\"PRAGMA table_info(products)\").all();
console.log('Products columns:', cols.map(c => c.name));

// Search for the product
const rows = db.prepare(\"SELECT * FROM products WHERE product_id LIKE '%B98D14%' OR name LIKE '%Anker%' OR name LIKE '%Bluetooth Speaker%'\").all();
